import Foundation
@testable import ProxyMirrorCore

func checkGRPC(_ test: CoreAssertions) throws {
    // Generated by the Protocol Buffers runtime from a proto3 descriptor with a streaming RPC.
    let descriptor = ""
    let framed = "AAAAAB0KDmZpeHR1cmUK5rGJ5a2XEgMBABgaAggBIAIoFQEAAAAxH4sIANhx9WoC/+PiS8usKCktSuV6trHz6drpQsyMDBJSTByMCkwaogBgG28NHQAAAAAAAAAA"
    guard let schemaBytes = Data(base64Encoded: descriptor), let body = Data(base64Encoded: framed) else {
        test.expect(false, "gRPC: fixture bytes")
        return
    }
    let schema = try GRPCSchema.parse(schemaBytes)
    let path = "/fixture.grpc.Echo/Talk"
    let input = schema.messageType(for: path, isRequest: true)
    let output = schema.messageType(for: path, isRequest: false)
    test.expect(input == "fixture.grpc.EchoRequest" && output == "fixture.grpc.EchoReply",
          "gRPC: descriptor resolves RPC input and output types")

    let scan = GRPCFrames.scan(body, complete: true, truncated: false)
    test.expect(scan.issue == nil && scan.messages.count == 3, "gRPC: multiple messages and empty message")
    if scan.messages.count == 3 {
        let plain = try GRPCFrames.payload(of: scan.messages[0], in: body, encoding: nil)
        let gzip = try GRPCFrames.payload(of: scan.messages[1], in: body, encoding: "gzip")
        let empty = try GRPCFrames.payload(of: scan.messages[2], in: body, encoding: nil)
        test.expect(plain == gzip && empty.isEmpty, "gRPC: gzip and zero-length payload")
        let text = try GRPCProtobuf.describe(plain, type: input, schema: schema)
        test.expect(text.contains("numbers [2]: [-1, 0, 12]") && text.contains("enabled [1]: true")
            && text.contains("state [4]: READY (2)") && text.contains("#5: 21"),
            "gRPC: typed packed, nested, enum and unknown fields")
    }
    let partial = GRPCFrames.scan(body.dropLast(2), complete: false, truncated: true)
    test.expect(partial.messages.count == 2 && partial.issue?.contains("捕获已截断") == true,
          "gRPC: truncated final header keeps complete messages")
    let status = GRPCFrames.status(headers: HTTPHeaders([("grpc-status", "0")]),
        trailers: HTTPHeaders([("grpc-status", "7"), ("grpc-message", "%E6%8B%92%E7%BB%9D%20x+y")]))
    test.expect(status.label == "7 · PERMISSION_DENIED" && status.message == "拒绝 x+y",
          "gRPC: trailers override initial status and decode status message")

    try checkGRPCWeb(test)

    // A complete 1 MiB + 1 frame is listed but exceeds the decoding limit.
    let oversized = Data([0, 0, 0x10, 0, 1]) + Data(repeating: 0, count: GRPCFrames.maxPayload + 1)
    let oversizedScan = GRPCFrames.scan(oversized, complete: true, truncated: false)
    test.equal(oversizedScan.messages.count, 1, "gRPC: oversized frame can be listed")
    if let message = oversizedScan.messages.first {
        test.rejects(try GRPCFrames.payload(of: message, in: oversized, encoding: nil),
                     with: GRPCInspectionError.self, "gRPC: oversized frame exceeds inspection budget")
    }
}

private func checkGRPCWeb(_ test: CoreAssertions) throws {
    test.equal(GRPCFrames.contentType(" Application/GRPC-Web ; charset=UTF-8")?.transport,
               .webBinary, "gRPC-Web: binary MIME type ignores case and parameters")
    let media = GRPCFrames.contentType("application/grpc-web-text+json")
    test.expect(media?.transport == .webText && media?.format == "json", "gRPC-Web: text MIME and format")
    test.equal(GRPCFrames.contentType("application/grpc-websocket"), nil, "gRPC-Web: unrelated MIME is ignored")

    func frame(_ flag: UInt8, _ payload: Data) -> Data {
        let length = UInt32(payload.count)
        return Data([flag, UInt8(truncatingIfNeeded: length >> 24), UInt8(truncatingIfNeeded: length >> 16),
                     UInt8(truncatingIfNeeded: length >> 8), UInt8(truncatingIfNeeded: length)]) + payload
    }
    let protobuf = Data([10, 2, 111, 107])
    let message = frame(0, protobuf)
    let trailer = frame(0x80, Data("grpc-status: 7\r\ngrpc-message: not%20available\r\nx-test: a\r\nx-test: b".utf8))
    let response = message + trailer

    var binary = GRPCFrames.Scanner()
    let partial = binary.scan(response.dropLast(), complete: false, truncated: false, transport: .webBinary)
    test.expect(partial.messages.count == 1 && partial.trailers.count == 0
        && partial.issue?.contains("仍在接收") == true, "gRPC-Web: partial trailers leave complete message available")
    let finished = binary.scan(response, complete: true, truncated: false, transport: .webBinary)
    test.expect(finished.messages.count == 1 && finished.trailers.values(of: "x-test") == ["a", "b"]
        && finished.issue == nil, "gRPC-Web: trailing metadata preserves duplicate values")
    let status = GRPCFrames.status(headers: HTTPHeaders([("grpc-status", "0")]), trailers: finished.trailers)
    test.expect(status.label == "7 · PERMISSION_DENIED" && status.message == "not available",
                "gRPC-Web: body trailers override initial status")
    let extra = binary.scan(response + message, complete: true, truncated: false, transport: .webBinary)
    test.expect(extra.messages.count == 1 && extra.issue?.contains("之后仍有数据") == true,
                "gRPC-Web: frames after trailers are invalid")

    let encoded = response.prefix(4).base64EncodedData() + response.dropFirst(4).base64EncodedData()
    var text = GRPCFrames.Scanner()
    for end in 1..<encoded.count {
        _ = text.scan(encoded.prefix(end), complete: false, truncated: false, transport: .webText)
    }
    let decoded = text.scan(encoded, complete: true, truncated: false, transport: .webText)
    let bytes = text.frameData(encoded, transport: .webText)
    test.expect(decoded.messages == finished.messages && decoded.trailers.values(of: "x-test") == ["a", "b"]
        && decoded.issue == nil && bytes == response, "gRPC-Web: incremental text with padding inside a frame")
    if let selected = decoded.messages.first {
        let unframed = try GRPCFrames.payload(of: selected, in: bytes, encoding: nil)
        test.equal(unframed, protobuf, "gRPC-Web: text mode passes decoded message to Protobuf")
    }
    let invalid = text.scan(encoded + Data("AA=A".utf8), complete: true, truncated: false, transport: .webText)
    test.expect(invalid.messages.count == 1 && invalid.issue?.contains("Base64 无效") == true,
                "gRPC-Web: malformed Base64 retains already decoded messages")
    var truncated = GRPCFrames.Scanner()
    let truncatedText = truncated.scan(encoded.dropLast(), complete: false, truncated: true, transport: .webText)
    test.expect(truncatedText.messages.count == 1 && truncatedText.issue?.contains("捕获已截断") == true,
                "gRPC-Web: incomplete final Base64 group reports capture limit")

    var malformed = GRPCFrames.Scanner()
    let malformedScan = malformed.scan(message + frame(0x80, Data("bad header: value".utf8)), complete: true,
                                       truncated: false, transport: .webBinary)
    test.expect(malformedScan.messages.count == 1 && malformedScan.issue?.contains("Trailers 头部格式无效") == true,
                "gRPC-Web: invalid trailer field does not invalidate messages")
    var reservedFlag = GRPCFrames.Scanner()
    test.expect(reservedFlag.scan(frame(0x82, Data()), complete: true, truncated: false, transport: .webBinary)
        .issue?.contains("无效的帧标记") == true, "gRPC-Web: reserved flag is invalid")
    var trailersOnly = GRPCFrames.Scanner()
    let empty = trailersOnly.scan(Data(), complete: true, truncated: false, transport: .webBinary)
    let headerStatus = GRPCFrames.status(headers: HTTPHeaders([("grpc-status", "12")]), trailers: empty.trailers)
    test.expect(empty.messages.isEmpty && empty.issue == nil && headerStatus.label == "12 · UNIMPLEMENTED",
                "gRPC-Web: trailers-only status works with no body")
    let compressedTrailers = Data(base64Encoded: "H4sIAAAAAAAC/0svKkjWLS5JLCkttlIw4OUCAP1sJKsQAAAA")!
    let compressedFrame = frame(0x81, compressedTrailers)
    var badCompression = GRPCFrames.Scanner()
    let failed = badCompression.scan(compressedFrame, complete: true, truncated: false, transport: .webBinary)
    test.expect(failed.issue?.contains("grpc-encoding") == true, "gRPC-Web: compressed trailers need grpc-encoding")
    var compression = GRPCFrames.Scanner()
    let uncompressed = compression.scan(compressedFrame, complete: true, truncated: false,
                                        transport: .webBinary, encoding: "gzip")
    test.expect(uncompressed.issue == nil && uncompressed.trailers.value(of: "grpc-status") == "0",
                "gRPC-Web: gzip-compressed trailers decode")
}
